import argparse
import logging
import requests
from datetime import datetime
import sys

def setup_logging():
    logging.basicConfig(
        filename='check.log',
        level=logging.INFO,
        format='%(asctime)s %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )

def process_url(url):
    try:
        response = requests.get(url, timeout=5)
        status_code = response.status_code
        if 200 <= status_code < 300:
            return True
        else:
            return False
    except requests.exceptions.RequestException as e:
        logging.error(f"ERROR: {str(e)}")
        return False

def main():
    parser = argparse.ArgumentParser(description='Check URLs and log results.')
    parser.add_argument('input_file', type=str, help='Path to the text file containing URLs')
    args = parser.parse_args()

    setup_logging()
    successful = 0
    failed = 0

    with open(args.input_file, 'r') as file:
        for line in file:
            url = line.strip()
            if url:
                success = process_url(url)
                if success:
                    successful += 1
                else:
                    failed += 1

    print(f"Processed {len(file)} URLs: {successful} successful, {failed} failed")

if __name__ == "__main__":
    main()

import sys
import requests
from urllib.parse import urlparse

def check_url(url):
    try:
        response = requests.get(url, timeout=5)
        return response.status_code
    except requests.exceptions.RequestException as e:
        return f"ERROR: {str(e)}"

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_urls.py <input_file>")
        sys.exit(1)

    input_file = sys.argv[1]
    log_file = "check.log"

    with open(input_file, 'r') as f:
        urls = [line.strip() for line in f if line.strip()]

    successful = 0
    failed = 0

    with open(log_file, 'w') as log:
        for url in urls:
            status = check_url(url)
            log.write(f"{url}\n{status}\n")
            if isinstance(status, int) and 200 <= status <= 299:
                successful += 1
            else:
                failed += 1

    print(f"Processed {len(urls)} URLs: {successful} successful, {failed} failed")

if __name__ == "__main__":
    main()

